<script lang="ts">import {enhance} from '$app/forms'; import {page} from '$app/state'; import ImportStepper from '$lib/components/academic/ImportStepper.svelte'; let {data,form}=$props(); let busy=$state<string|null>(null); const rows=$derived(data.rows??[]); const warnings=$derived(rows.flatMap((r:any)=>r.import_issues??[]).filter((i:any)=>i.issue_type==='warning')); const unack=$derived(warnings.filter((i:any)=>!i.acknowledged_at).length); const changed=$derived(rows.filter((r:any)=>r.status==='changed').length); const unchanged=$derived(rows.filter((r:any)=>r.status==='unchanged'||r.status==='skipped').length); const added=$derived(rows.filter((r:any)=>r.status==='valid').length); const rowCourse=(r:any)=>r.normalized_payload?.courseCode??r.raw_payload?.course_code??r.raw_payload?.course??'—'; const rowSection=(r:any)=>r.normalized_payload?.sectionCode??r.raw_payload?.section_code??r.raw_payload?.section??'—'; const rowSchedule=(r:any)=>{const p=r.normalized_payload;if(!p)return'Could not normalize';return `${Array.isArray(p.weekdays)?p.weekdays.join(' · '):'—'} · ${p.startsAt??'—'}–${p.endsAt??'—'} · ${p.roomId??'TBA'}`;};</script>
<svelte:head><title>Import Review · IMS Academic Hub</title></svelte:head>
<header class="flex flex-col gap-3 border-b border-line pb-4 sm:flex-row sm:items-start sm:justify-between"><div><a class="inline-flex min-h-11 items-center font-bold text-ims-blue-ink" href="/admin/imports">← All Imports</a><p class="font-mono text-xs uppercase tracking-[.14em] text-ims-blue-ink">Import review</p><h2 class="mt-1 text-4xl font-semibold tracking-[-.05em]">{data.batch.filename??'Schedule batch'}</h2><p class="text-muted">{data.source?.label??'Unknown source'} · {data.term?`${data.term.academicYear} · ${data.term.termName}`:'Unknown term'}</p></div><span class={`w-fit border px-2 py-1 text-xs font-bold capitalize ${data.batch.status==='ready'?'border-yellow-300 bg-yellow-50 text-amber-900':data.batch.status==='validation_failed'?'border-red-200 bg-red-50 text-red-800':data.batch.status==='applied'?'border-green-200 bg-green-50 text-green-800':'border-line'}`}>{data.batch.status.replace('_',' ')}</span></header><div class="mt-4"><ImportStepper current={3}/></div>
{#if page.url.searchParams.get('applied')==='1'}<div class="mb-4 border-l-4 border-ims-green bg-green-50 p-3 text-green-900" role="status"><strong>Batch applied.</strong> Records remain unpublished until review.</div>{/if}{#if form?.actionError}<div class="mb-4 border-l-4 border-danger bg-red-50 p-3 text-red-900" role="alert">{form.actionError}</div>{/if}
<div class="grid grid-cols-2 border-y border-line bg-white lg:grid-cols-4">{#each [['New',added,'not seen before'],['Changed',changed,'needs review'],['Unchanged',unchanged,'safe to skip'],['Errors',data.batch.error_count,'must be zero']] as metric}<article class="grid gap-1 border-b border-r border-line p-3"><span class="text-sm text-muted">{metric[0]}</span><strong class="font-mono text-3xl">{metric[1]}</strong><small class="text-muted">{metric[2]}</small></article>{/each}</div>
<section class="mt-4 grid gap-4 border-l-4 border-ims-yellow bg-white p-4 lg:grid-cols-[1fr_auto] lg:items-center"><div><p class="font-mono text-xs uppercase tracking-[.12em] text-ims-blue-ink">Apply gate</p><h3 class="text-xl font-semibold">{data.batch.status==='ready'?'Validation passed':'Batch is not ready to apply'}</h3><p class="max-w-prose leading-relaxed text-muted">Applying is transactional. Changed records move back to <strong>needs verification</strong>.</p></div><div class="flex flex-wrap items-center gap-2">{#if unack>0}<form method="POST" action="?/acknowledgeWarnings" use:enhance={()=>{busy='ack';return async({update})=>{busy=null;await update();};}}><button class="min-h-11 border border-line-strong px-3 font-bold" disabled={busy!==null}>{busy==='ack'?'Acknowledging…':`Acknowledge ${unack} Warning${unack===1?'':'s'}`}</button></form>{/if}{#if data.batch.status==='ready'}<button class="min-h-11 bg-ims-blue-deep px-3 font-bold text-white opacity-45" type="button" disabled aria-describedby="apply-lock-note">Apply Reviewed Batch</button><span class="max-w-xs text-xs text-muted" id="apply-lock-note">Locked until RLS hardening and idempotent diff support are verified.</span>{/if}{#if data.canApply&&['staged','validation_failed','ready'].includes(data.batch.status)}<form method="POST" action="?/reject" use:enhance={()=>{busy='reject';return async({update})=>{busy=null;await update();};}}><button class="min-h-11 px-3 font-bold text-danger" disabled={busy!==null}>{busy==='reject'?'Rejecting…':'Reject Batch'}</button></form>{/if}</div></section>
<section class="mt-4 border border-line-strong bg-white p-4"><header class="flex justify-between border-b border-line pb-3"><div><p class="font-mono text-xs uppercase tracking-[.12em] text-ims-blue-ink">Normalized preview</p><h3 class="text-xl font-semibold">Rows</h3></div><span class="text-sm text-muted">{rows.length} rows · {warnings.length} warnings</span></header>{#if rows.length}<div class="mt-3 overflow-auto overscroll-contain border border-line" role="region" aria-label="Scrollable import preview table"><table class="w-full min-w-[850px] border-collapse text-sm"><thead><tr class="bg-slate-50 text-left text-xs uppercase tracking-wide text-muted">{#each ['Row','Status','Course / section','Normalized meeting','Issues'] as heading}<th class="sticky top-0 bg-slate-50 p-3">{heading}</th>{/each}</tr></thead><tbody>{#each rows as row}<tr class="border-t border-line align-top"><td class="p-3 font-mono text-muted">{row.row_number}</td><td class="p-3"><span class={`border px-2 py-1 text-xs font-bold capitalize ${row.status==='invalid'?'border-red-200 bg-red-50 text-red-800':row.status==='changed'?'border-yellow-300 bg-yellow-50 text-amber-900':row.status==='unchanged'||row.status==='skipped'?'border-line bg-slate-50 text-muted':'border-green-200 bg-green-50 text-green-800'}`}>{row.status}</span></td><td class="p-3"><strong>{rowCourse(row)}</strong><small class="block text-muted">Section {rowSection(row)}</small></td><td class="p-3 font-mono whitespace-nowrap">{rowSchedule(row)}</td><td class="p-3">{#if row.import_issues?.length}<div class="grid min-w-64 gap-2">{#each row.import_issues as issue}<div class={`border-l-4 p-2 ${issue.issue_type==='error'?'border-danger bg-red-50':'border-amber-500 bg-yellow-50'}`}><strong class="block text-xs uppercase">{issue.error_code}</strong><span>{issue.message}</span>{#if issue.normalized_value}<small class="block text-muted">Normalized: {issue.normalized_value}</small>{/if}</div>{/each}</div>{:else}<span class="text-muted">No issues</span>{/if}</td></tr>{/each}</tbody></table></div>{:else}<div class="p-6 text-center text-muted">No rows were staged for this batch.</div>{/if}</section>
